1	// pattern: Imperative Shell
2	//
3	// Gathers: session state (access_token, refresh_token, expiry, nonce), request params
4	// Processes: lazy refresh → DPoP proof → header attachment → nonce retry
5	// Returns: reqwest::Response or OAuthError
6	
7	use std::sync::{Arc, Mutex};
8	
9	use reqwest::{Client, Response};
10	use serde::Serialize;
11	
12	use crate::oauth::{DPoPKeypair, OAuthError, OAuthSession};
13	
14	/// Authenticated HTTP client.
15	///
16	/// Wraps every request with:
17	/// - `Authorization: DPoP {access_token}` header
18	/// - `DPoP: {proof}` header containing a fresh ES256 JWT with `ath` claim
19	///
20	/// Transparently refreshes the access token when it has less than 60 seconds remaining.
21	/// Retries once on `use_dpop_nonce` 400 responses.
22	pub struct OAuthClient {
23	    inner: Client,
24	    dpop: DPoPKeypair,
25	    session: Arc<Mutex<OAuthSession>>,
26	    base_url: String,
27	}
28	
29	impl OAuthClient {
30	    /// Construct from an existing session.
31	    ///
32	    /// Loads the DPoP keypair from Keychain (same key used in the original flow).
33	    ///
34	    /// `Client::new()` inherits the TLS backend configured at the crate level via Cargo features
35	    /// (`default-features = false, features = ["rustls-tls"]` in Cargo.toml). No builder
36	    /// configuration is needed — the feature flags apply crate-wide, not per-client-instance.
37	    pub fn new(session: Arc<Mutex<OAuthSession>>, base_url: String) -> Result<Self, OAuthError> {
38	        let dpop = DPoPKeypair::get_or_create()?;
39	        Ok(Self {
40	            inner: Client::new(),
41	            dpop,
42	            session,
43	            base_url,
44	        })
45	    }
46	
47	    /// GET `{base_url}/{path}` with DPoP authentication.
48	    pub async fn get(&self, path: &str) -> Result<Response, OAuthError> {
49	        let url = format!("{}/{}", self.base_url, path.trim_start_matches('/'));
50	        self.execute_with_retry(reqwest::Method::GET, &url, None::<&()>)
51	            .await
52	    }
53	
54	    /// POST `{base_url}/{path}` with JSON body and DPoP authentication.
55	    pub async fn post<B: Serialize + Sync>(
56	        &self,
57	        path: &str,
58	        body: &B,
59	    ) -> Result<Response, OAuthError> {
60	        let url = format!("{}/{}", self.base_url, path.trim_start_matches('/'));
61	        self.execute_with_retry(reqwest::Method::POST, &url, Some(body))
62	            .await
63	    }
64	
65	    // ── Internal ──────────────────────────────────────────────────────────────
66	
67	    /// Build and send a request with DPoP headers, retrying once on `use_dpop_nonce`.
68	    async fn execute_with_retry<B: Serialize + Sync>(
69	        &self,
70	        method: reqwest::Method,
71	        url: &str,
72	        body: Option<&B>,
73	    ) -> Result<Response, OAuthError> {
74	        // Lazy refresh before reading the access token.
75	        self.maybe_refresh_token().await?;
76	
77	        let nonce_opt = {
78	            let s = self.session.lock().unwrap();
79	            s.dpop_nonce.clone()
80	        };
81	
82	        let resp = self
83	            .send_with_dpop(&method, url, body, nonce_opt.as_deref())
84	            .await?;
85	
86	        // On use_dpop_nonce, extract the server nonce from the DPoP-Nonce header,
87	        // update session, and retry once.
88	        if resp.status().as_u16() == 400 {
89	            // Extract nonce header BEFORE consuming the body.
90	            let maybe_nonce = resp
91	                .headers()
92	                .get("DPoP-Nonce")
93	                .and_then(|v| v.to_str().ok())
94	                .map(str::to_string);
95	
96	            // Now consume the body to check the error type.
97	            let error_body = resp.text().await.unwrap_or_default();
98	
99	            // Parse the error response to check for use_dpop_nonce.
100	            let is_use_dpop_nonce = {
101	                serde_json::from_str::<serde_json::Value>(&error_body)
102	                    .ok()
103	                    .and_then(|v| v.get("error")?.as_str().map(|e| e == "use_dpop_nonce"))
104	                    .unwrap_or(false)
105	            };
106	
107	            if is_use_dpop_nonce {
108	                if let Some(fresh_nonce) = maybe_nonce {
109	                    {
110	                        let mut s = self.session.lock().unwrap();
111	                        s.dpop_nonce = Some(fresh_nonce.clone());
112	                    }
113	                    tracing::debug!(nonce = %fresh_nonce, "retrying request with server DPoP nonce");
114	                    // Do NOT re-check expiry on the retry — avoid double-refresh.
115	                    return self
116	                        .send_with_dpop(&method, url, body, Some(&fresh_nonce))
117	                        .await;
118	                } else {
119	                    // use_dpop_nonce but no nonce header — this is an error.
120	                    tracing::error!("use_dpop_nonce response missing DPoP-Nonce header");
121	                    return Err(OAuthError::NotAuthenticated);
122	                }
123	            } else {
124	                // Not use_dpop_nonce — the body has been consumed, so we can't return it.
125	                // Treat as auth failure since the request cannot proceed.
126	                tracing::error!(body = %error_body, "400 response without use_dpop_nonce error");
127	                return Err(OAuthError::NotAuthenticated);
128	            }
129	        }
130	
131	        Ok(resp)
132	    }
133	
134	    /// Send a single request with `Authorization: DPoP` and `DPoP: {proof}` headers.
135	    async fn send_with_dpop<B: Serialize + Sync>(
136	        &self,
137	        method: &reqwest::Method,
138	        url: &str,
139	        body: Option<&B>,
140	        nonce: Option<&str>,
141	    ) -> Result<Response, OAuthError> {
142	        let (access_token, ath) = {
143	            let s = self.session.lock().unwrap();
144	            let ath = DPoPKeypair::compute_ath(&s.access_token);
145	            (s.access_token.clone(), ath)
146	        };
147	
148	        let proof = self
149	            .dpop
150	            .make_proof(method.as_str(), url, nonce, Some(&ath))?;
151	
152	        let mut builder = match method {
153	            m if *m == reqwest::Method::GET => self.inner.get(url),
154	            m if *m == reqwest::Method::POST => self.inner.post(url),
155	            _ => return Err(OAuthError::NotAuthenticated),
156	        };
157	
158	        builder = builder
159	            .header("Authorization", format!("DPoP {access_token}"))
160	            .header("DPoP", &proof);
161	
162	        if let (Some(b), m) = (body, method) {
163	            if *m == reqwest::Method::POST {
164	                builder = builder.json(b);
165	            }
166	        }
167	
168	        builder.send().await.map_err(|e| {
169	            tracing::error!(error = %e, "OAuthClient request network error");
170	            OAuthError::NotAuthenticated
171	        })
172	    }
173	
174	    /// Refresh the access token if it expires within the next 60 seconds.
175	    async fn maybe_refresh_token(&self) -> Result<(), OAuthError> {
176	        let should_refresh = {
177	            let s = self.session.lock().unwrap();
178	            let now = std::time::SystemTime::now()
179	                .duration_since(std::time::UNIX_EPOCH)
180	                .map_err(|_| OAuthError::TokenRefreshFailed)?
181	                .as_secs();
182	            s.expires_at < now + 60
183	        };
184	
185	        if should_refresh {
186	            self.refresh_token().await?;
187	        }
188	        Ok(())
189	    }
190	
191	    /// POST `/oauth/token` with `grant_type=refresh_token` — no `ath` claim in DPoP proof.
192	    ///
193	    /// Updates `self.session` with the new tokens and persists to Keychain.
194	    /// Surfaces all errors to the caller — no silent swallowing.
195	    pub async fn refresh_token(&self) -> Result<(), OAuthError> {
196	        let (refresh_token, nonce_opt) = {
197	            let s = self.session.lock().unwrap();
198	            (s.refresh_token.clone(), s.dpop_nonce.clone())
199	        };
200	
201	        let token_htu = format!("{}/oauth/token", self.base_url);
202	        let proof = self
203	            .dpop
204	            .make_proof("POST", &token_htu, nonce_opt.as_deref(), None)?;
205	
206	        let resp = self
207	            .inner
208	            .post(&token_htu)
209	            .header("DPoP", &proof)
210	            .form(&[
211	                ("grant_type", "refresh_token"),
212	                ("refresh_token", refresh_token.as_str()),
213	                ("client_id", "dev.malpercio.identitywallet"),
214	            ])
215	            .send()
216	            .await
217	            .map_err(|e| {
218	                tracing::error!(error = %e, "token refresh network error");
219	                OAuthError::TokenRefreshFailed
220	            })?;
221	
222	        // On use_dpop_nonce from the refresh endpoint, retry once with the nonce.
223	        if resp.status().as_u16() == 400 {
224	            let retry_nonce = resp
225	                .headers()
226	                .get("DPoP-Nonce")
227	                .and_then(|v| v.to_str().ok())
228	                .map(str::to_string);
229	
230	            if let Some(nonce_val) = retry_nonce {
231	                let proof2 = self
232	                    .dpop
233	                    .make_proof("POST", &token_htu, Some(&nonce_val), None)?;
234	                let resp2 = self
235	                    .inner
236	                    .post(&token_htu)
237	                    .header("DPoP", &proof2)
238	                    .form(&[
239	                        ("grant_type", "refresh_token"),
240	                        ("refresh_token", refresh_token.as_str()),
241	                        ("client_id", "dev.malpercio.identitywallet"),
242	                    ])
243	                    .send()
244	                    .await
245	                    .map_err(|_| OAuthError::TokenRefreshFailed)?;
246	
247	                if resp2.status().as_u16() == 200 {
248	                    return self.apply_token_response(resp2).await;
249	                }
250	
251	                // Check for invalid_grant after nonce retry.
252	                if resp2.status().as_u16() == 400 {
253	                    let body = resp2.text().await.unwrap_or_default();
254	                    if let Ok(err) = serde_json::from_str::<serde_json::Value>(&body) {
255	                        if err.get("error").and_then(|e| e.as_str()) == Some("invalid_grant") {
256	                            tracing::error!("refresh token invalid after nonce retry");
257	                            return Err(OAuthError::InvalidGrant);
258	                        }
259	                    }
260	                    tracing::error!(body = %body, "token refresh failed after nonce retry");
261	                    return Err(OAuthError::TokenRefreshFailed);
262	                }
263	
264	                tracing::error!("token refresh failed after nonce retry");
265	                return Err(OAuthError::TokenRefreshFailed);
266	            }
267	
268	            // No nonce header, check the error body for invalid_grant.
269	            let body = resp.text().await.unwrap_or_default();
270	            if let Ok(err) = serde_json::from_str::<serde_json::Value>(&body) {
271	                if err.get("error").and_then(|e| e.as_str()) == Some("invalid_grant") {
272	                    tracing::error!("refresh token invalid");
273	                    return Err(OAuthError::InvalidGrant);
274	                }
275	            }
276	            tracing::error!(body = %body, "token refresh 400 without nonce header");
277	            return Err(OAuthError::TokenRefreshFailed);
278	        }
279	
280	        if resp.status().as_u16() != 200 {
281	            let body = resp.text().await.unwrap_or_default();
282	            tracing::error!(body = %body, "token refresh failed");
283	            return Err(OAuthError::TokenRefreshFailed);
284	        }
285	
286	        self.apply_token_response(resp).await
287	    }
288	
289	    /// Construct with a custom base URL and pre-built keypair (test use only).
290	    #[cfg(test)]
291	    pub fn new_for_test(
292	        keypair: DPoPKeypair,
293	        session: Arc<Mutex<OAuthSession>>,
294	        base_url: String,
295	    ) -> Self {
296	        Self {
297	            inner: Client::new(),
298	            dpop: keypair,
299	            session,
300	            base_url,
301	        }
302	    }
303	
304	    /// Deserialize a 200 token response and update session + Keychain.
305	    async fn apply_token_response(&self, resp: Response) -> Result<(), OAuthError> {
306	        // Capture the DPoP-Nonce header before consuming the response body.
307	        let new_nonce = resp
308	            .headers()
309	            .get("DPoP-Nonce")
310	            .and_then(|v| v.to_str().ok())
311	            .map(str::to_string);
312	
313	        let token_resp: crate::http::TokenResponse = resp.json().await.map_err(|e| {
314	            tracing::error!(error = %e, "token refresh response deserialization failed");
315	            OAuthError::TokenRefreshFailed
316	        })?;
317	
318	        let expires_at = std::time::SystemTime::now()
319	            .duration_since(std::time::UNIX_EPOCH)
320	            .map_err(|_| OAuthError::TokenRefreshFailed)?
321	            .as_secs()
322	            + token_resp.expires_in;
323	
324	        crate::keychain::store_oauth_tokens(&token_resp.access_token, &token_resp.refresh_token)
325	            .map_err(|_| OAuthError::KeychainError)?;
326	
327	        let mut s = self.session.lock().unwrap();
328	        s.access_token = token_resp.access_token;
329	        s.refresh_token = token_resp.refresh_token;
330	        s.expires_at = expires_at;
331	        s.dpop_nonce = new_nonce;
332	
333	        tracing::info!("access token refreshed");
334	        Ok(())
335	    }
336	}
