pub async fn describe_server(
    pds_client: &PdsClient,
    base_url: &str,
) -> Result<String, MigrateError> {
    let url = format!(
        "{}/xrpc/com.atproto.server.describeServer",
        base_url.trim_end_matches('/')
    );
    let resp =
        pds_client
            .client()
            .get(&url)
            .send()
            .await
            .map_err(|e| MigrateError::NetworkError {
                message: format!("describeServer request failed: {e}"),
            })?;

    let status = resp.status();
    if !status.is_success() {
        let body = resp
            .text()
            .await
            .unwrap_or_else(|_| "(response body unreadable)".to_string());
        return Err(MigrateError::NetworkError {
            message: format!("describeServer returned {status}: {body}"),
        });
    }

    let body: serde_json::Value = resp.json().await.map_err(|e| MigrateError::NetworkError {
        message: format!("failed to parse describeServer response: {e}"),
    })?;
    body.get("did")
        .and_then(|v| v.as_str())
        .map(String::from)
        .ok_or_else(|| MigrateError::NetworkError {
            message: "describeServer response missing 'did'".to_string(),
        })
}

/// POST `{base_url}/xrpc/com.atproto.server.reserveSigningKey` (public) with `{ "did": did }`,
/// reserving a repo signing key for the migrating DID on the destination ahead of
/// `createAccount`. The response's `signingKey` is not needed by the caller (it becomes
/// the destination's recommended rotation key, discovered later via
/// `getRecommendedDidCredentials`), so this only reports success/failure.
pub async fn reserve_signing_key(
    pds_client: &PdsClient,
    base_url: &str,
    did: &str,
) -> Result<(), MigrateError> {
    let url = format!(
        "{}/xrpc/com.atproto.server.reserveSigningKey",
        base_url.trim_end_matches('/')
    );
    let resp = pds_client
        .client()
        .post(&url)
        .json(&serde_json::json!({ "did": did }))
        .send()
        .await
        .map_err(|e| MigrateError::NetworkError {
            message: format!("reserveSigningKey request failed: {e}"),
        })?;

    if resp.status().is_success() {
        Ok(())
    } else {
        let status = resp.status();
        let body = resp
            .text()
            .await
            .unwrap_or_else(|_| "(response body unreadable)".to_string());
        Err(MigrateError::NetworkError {
            message: format!("reserveSigningKey returned {status}: {body}"),
        })
    }
}

/// GET `com.atproto.server.getServiceAuth?aud=..&lxm=..` on the SOURCE (via its
/// authenticated `OAuthClient`), minting a service-auth JWT scoped to the destination's
/// `createAccount` method. Returns the raw `token` string.
pub async fn get_service_auth(
    source_oauth_client: &OAuthClient,
    aud: &str,
    lxm: &str,
) -> Result<String, MigrateError> {
    let path = format!(
        "/xrpc/com.atproto.server.getServiceAuth?aud={}&lxm={}",
        urlencoding::encode(aud),
        urlencoding::encode(lxm)
    );
    let resp = source_oauth_client
        .get(&path)
        .await
        .map_err(|e| MigrateError::NetworkError {
            message: format!("getServiceAuth request failed: {e}"),
        })?;

    let status = resp.status();
    if !status.is_success() {
        let body = resp
            .text()
            .await
            .unwrap_or_else(|_| "(response body unreadable)".to_string());
        return Err(MigrateError::NetworkError {
            message: format!("getServiceAuth returned {status}: {body}"),
        });
    }

    let body: serde_json::Value = resp.json().await.map_err(|e| MigrateError::NetworkError {
        message: format!("failed to parse getServiceAuth response: {e}"),
    })?;
    body.get("token")
        .and_then(|v| v.as_str())
        .map(String::from)
        .ok_or_else(|| MigrateError::NetworkError {
            message: "getServiceAuth response missing 'token'".to_string(),
        })
}

/// POST `{dest_base_url}/xrpc/com.atproto.server.createAccount`, authorized by the
/// source-minted service JWT (`Authorization: Bearer {service_jwt}` — NOT the wallet's own
/// session), with body `{ handle, email, did }`. On success, returns the destination's
/// plain bearer session (`{ accessJwt, refreshJwt }`); the destination creates the account
/// deactivated and repo-less, ready for `importRepo`.
///
/// A rejection (bad/expired service JWT, handle taken, etc.) maps to
/// `MigrateError::PlcDirectoryError` — matching the vocabulary `submit_migration_op` already
/// uses for "the network operation was rejected by the counterparty", here the destination
/// PDS rather than plc.directory.
pub async fn create_dest_account(
    dest_base_url: &str,
    service_jwt: &str,
    did: &str,
    handle: &str,
    email: &str,
) -> Result<crate::bearer_client::BearerSession, MigrateError> {
    let url = format!(
        "{}/xrpc/com.atproto.server.createAccount",
        dest_base_url.trim_end_matches('/')
    );
    let client = reqwest::Client::new();
    let resp = client
        .post(&url)
        .bearer_auth(service_jwt)
        .json(&serde_json::json!({
            "handle": handle,
            "email": email,
            "did": did,
        }))
        .send()
        .await
        .map_err(|e| MigrateError::NetworkError {
            message: format!("createAccount request failed: {e}"),
        })?;

    let status = resp.status();
    if !status.is_success() {
        let body = resp
            .text()
            .await
            .unwrap_or_else(|_| "(response body unreadable)".to_string());
        return Err(MigrateError::PlcDirectoryError {
            message: format!("destination createAccount rejected: {status}: {body}"),
        });
    }

    #[derive(Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct CreateAccountResponse {
        access_jwt: String,
        refresh_jwt: String,
    }

    let body: CreateAccountResponse =
        resp.json().await.map_err(|e| MigrateError::NetworkError {
            message: format!("failed to parse createAccount response: {e}"),
        })?;

    Ok(crate::bearer_client::BearerSession {
        access_jwt: body.access_jwt,
        refresh_jwt: body.refresh_jwt,
    })
}

/// Which outbound-migration authorization path the wallet should use for a DID.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum MigrationPath {
    /// The wallet holds an authorized rotation key and can self-sign the PLC op.
    SelfSigned,
    /// The wallet does not hold an authorized rotation key; use the PDS-signed interop path.
    Interop,
    /// The wallet cannot safely choose a path (for example, plc.directory is unreachable).
    CannotDetermine,
}

/// Result of deciding which outbound-migration path applies to a DID.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct MigrationPathDecision {
    pub path: MigrationPath,
    /// The wallet's per-DID device key, when available.
    pub device_key_id: Option<String>,
    /// Index of the device key in the DID's current rotationKeys, if present.
    pub rotation_key_index: Option<usize>,
    /// Human-readable explanation for UI/orchestrator logging.
    pub reason: String,
}

// ── Pure inputs to the guard ─────────────────────────────────────────────────

/// The facts the strict pre-sign guard needs to decide whether a proposed migration
/// operation is safe to sign. Deliberately flattened to plain strings/vecs so the
/// guard is a pure, trivially testable function.
#[derive(Debug, Clone)]
pub struct MigrationInputs {
    /// The wallet's per-DID device key (`did:key:z...`). Must remain at rotationKeys[0].
    pub device_key_id: String,
    /// The DID's CURRENT rotation keys (from the latest audit-log op).

fn source_pds_url_from_stored_did_doc(doc_json: &str) -> Result<String, MigrateError> {
    let doc: serde_json::Value =
        serde_json::from_str(doc_json).map_err(|e| MigrateError::IdentityNotFound {
            message: format!("stored DID document is not valid JSON: {e}"),
        })?;
    doc.get("services")
        .and_then(|s| s.get(ATPROTO_PDS_SERVICE_ID))
        .and_then(|svc| svc.get("endpoint"))
        .and_then(|e| e.as_str())
        .map(String::from)
        .ok_or_else(|| MigrateError::IdentityNotFound {
            message: "stored DID document has no atproto_pds service endpoint".to_string(),
        })
}

/// Resolve the source PDS endpoint, discover the destination's service DID, detect the
/// migration path, and park the initial `MigrationState`. This is the testable core of
/// `prepare_migration_cmd`, taking `&AppState` directly (rather than Tauri's `State`
/// wrapper) so it can be exercised without constructing a Tauri app.
pub async fn prepare_migration(
    app_state: &crate::oauth::AppState,
    pds_client: &PdsClient,
    did: String,
    dest_pds_url: String,
) -> Result<MigrationPathDecision, MigrateError> {
    let store = IdentityStore;
    let stored_doc = store
        .get_did_doc(&did)
        .map_err(|e| MigrateError::IdentityNotFound {
            message: format!("failed to load stored DID document: {e}"),
        })?
        .ok_or_else(|| MigrateError::IdentityNotFound {
            message: "no stored DID document for this identity".to_string(),
        })?;
    let source_pds_url = source_pds_url_from_stored_did_doc(&stored_doc)?;

    let dest_service_did = describe_server(pds_client, &dest_pds_url).await?;
    let decision = detect_migration_path(pds_client, &did).await;

    let migration_state = MigrationState {
        did: did.clone(),
        source_pds_url,
        dest_pds_url,
        dest_service_did: Some(dest_service_did),
        path: Some(decision.path.clone()),
        source_oauth_client: None,
        dest_session: None,
        signed_op: None,
    };

    let mut migration = app_state.migration_state.lock().await;
    *migration = Some(migration_state);

    Ok(decision)
}

/// Create the deactivated destination account for a migration already parked in
/// `MigrationState` (requires `source_oauth_client` + `dest_service_did`, populated by
/// `prepare_migration` + the source-auth commands). The testable core of
/// `migration_create_dest_account_cmd`.
///
/// Sequence: `reserveSigningKey`(dest, public) → `getServiceAuth`(source, scoped to
/// `aud=destServiceDid`, `lxm=com.atproto.server.createAccount`) →
/// `createAccount`(dest, Bearer=serviceJWT). On success, wraps the returned bearer
/// session in a `BearerClient` targeting the destination and stores it as
/// `MigrationState.dest_session`. A failure leaves `MigrationState` untouched (no
/// `dest_session`) so a retry can safely re-run — `reserveSigningKey`/`createAccount`(did=)
/// are idempotent on the server, matching AC2.5.
pub async fn migration_create_dest_account_impl(
    app_state: &crate::oauth::AppState,
    did: String,
    handle: String,
    email: String,
) -> Result<(), MigrateError> {
    let (source_oauth_client, dest_pds_url, dest_service_did) = {
        let migration = app_state.migration_state.lock().await;
        let ms = migration
            .as_ref()
            .ok_or_else(|| MigrateError::MigrationNotReady {
                message: "no pending migration; call prepare_migration first".to_string(),
            })?;
        if ms.did != did {
            return Err(MigrateError::MigrationNotReady {
                message: format!(
                    "migration state DID mismatch: expected {}, got {did}",
                    ms.did
                ),
            });
        }
        let source_oauth_client =
            ms.source_oauth_client
                .clone()
                .ok_or_else(|| MigrateError::MigrationNotReady {
