                        .to_string(),
                })?;
        let dest_service_did =
            ms.dest_service_did
                .clone()
                .ok_or_else(|| MigrateError::MigrationNotReady {
                    message: "destination service DID missing; run prepare_migration first"
                        .to_string(),
                })?;
