            source_oauth_client,
            ms.dest_pds_url.clone(),
            dest_service_did,
        )
    };

    reserve_signing_key(app_state.pds_client(), &dest_pds_url, &did).await?;
    let service_jwt = get_service_auth(
        &source_oauth_client,
        &dest_service_did,
        "com.atproto.server.createAccount",
    )
    .await?;
    let bearer_session =
