        dest_pds_url,
    );

    // Re-acquire and re-validate: a concurrent migration could have replaced the state
    // while the network calls above were in flight.
    let mut migration = app_state.migration_state.lock().await;
    let ms = migration
        .as_mut()
        .ok_or_else(|| MigrateError::MigrationNotReady {
            message: "pending migration was cleared while creating the destination account"
                .to_string(),
        })?;
    if ms.did != did {
        return Err(MigrateError::MigrationNotReady {
            message: format!(
                "migration state changed while creating the destination account: expected {}, got {did}",
                ms.did
            ),
        });
    }
    ms.dest_session = Some(Arc::new(dest_client));

    Ok(())
}

