pub async fn migration_complete_source_auth_impl(
    app_state: &crate::oauth::AppState,
    callback_url: String,
) -> Result<(), MigrateError> {
    // Take the parked flow — clears it so a stray second call can't reuse the verifier.
    let pending = app_state
        .pending_pds_login
        .lock()
        .unwrap()
        .take()
        .ok_or_else(|| MigrateError::MigrationNotReady {
            message: "no pending source authentication; call prepare_migration_source_auth first"
                .to_string(),
        })?;

    // Parse + CSRF-validate the callback URL before any token exchange.
    let (code, callback_state) = crate::oauth::parse_callback_url(&callback_url).map_err(|_| {
        MigrateError::MigrationNotReady {
            message: "malformed source-auth callback URL".to_string(),
        }
    })?;
    if callback_state != pending.csrf_state {
        return Err(MigrateError::MigrationNotReady {
            message: "source-auth CSRF state mismatch".to_string(),
        });
    }

    let pds_client = app_state.pds_client();
    let dpop =
        crate::oauth::DPoPKeypair::get_or_create().map_err(|e| MigrateError::NetworkError {
            message: format!("failed to create DPoP keypair: {e}"),
        })?;

    // Token exchange with nonce retry, reusing claim.rs's helper.
    let (token_resp, initial_nonce) = crate::claim::pds_exchange_code_with_retry(
        pds_client,
        &dpop,
        &code,
        &pending.pkce_verifier,
        &pending.metadata,
        &pending.client_id,
    )
    .await
    .map_err(|e| MigrateError::NetworkError {
        message: format!("source token exchange failed: {e}"),
    })?;

    // Build the OAuthClient targeting the source PDS.
    let session = Arc::new(std::sync::Mutex::new(crate::oauth::OAuthSession {
        access_token: token_resp.access_token,
        refresh_token: token_resp.refresh_token,
        expires_at: std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_err(|_| MigrateError::NetworkError {
                message: "system time error".to_string(),
            })?
            .as_secs()
            + token_resp.expires_in,
        dpop_nonce: initial_nonce,
    }));
    let oauth_client =
        OAuthClient::new(session, pending.oauth_client_pds_url.clone()).map_err(|e| {
            MigrateError::NetworkError {
                message: format!("failed to create source OAuth client: {e}"),
            }
        })?;

    // Re-validate against MigrationState and store the client.
    let mut migration = app_state.migration_state.lock().await;
    let ms = migration
        .as_mut()
        .ok_or_else(|| MigrateError::MigrationNotReady {
            message: "pending migration was cleared while the source auth session was open"
                .to_string(),
        })?;
    if ms.did != pending.did || ms.source_pds_url != pending.pds_url {
        return Err(MigrateError::MigrationNotReady {
            message: "migration state no longer matches the pending source auth".to_string(),
        });
    }
    ms.source_oauth_client = Some(Arc::new(oauth_client));

    Ok(())
}

