pub async fn migration_transfer_blobs_impl(
    app_state: &crate::oauth::AppState,
    did: String,
    on_progress: &mut (dyn FnMut(usize, usize) + Send),
) -> Result<(), MigrateError> {
    let (source_pds_url, dest_client) = {
        let migration = app_state.migration_state.lock().await;
        let ms = migration
            .as_ref()
            .ok_or_else(|| MigrateError::MigrationNotReady {
                message: "no pending migration; call prepare_migration first".to_string(),
            })?;
        if ms.did != did {
            return Err(MigrateError::MigrationNotReady {
                message: format!(
                    "migration state DID mismatch: expected {}, got {did}",
                    ms.did
                ),
            });
        }
        let dest_client = ms
            .dest_session
            .clone()
            .ok_or_else(|| MigrateError::MigrationNotReady {
                message: "destination session missing; create the destination account first"
                    .to_string(),
            })?;
        (ms.source_pds_url.clone(), dest_client)
    };

    // 1. Collect every blob CID across pagination.
    let mut cids: Vec<String> = Vec::new();
    let mut cursor: Option<String> = None;
    loop {
        let (page, next_cursor) = list_blobs(
            app_state.pds_client(),
            &source_pds_url,
            &did,
            cursor.as_deref(),
        )
        .await?;
        cids.extend(page);
        match next_cursor {
            Some(c) => cursor = Some(c),
            None => break,
        }
    }

    // 2. Download each from the source, re-upload to the destination, reporting progress.
    let total = cids.len();
    for (i, cid) in cids.iter().enumerate() {
        let bytes = get_blob(app_state.pds_client(), &source_pds_url, &did, cid).await?;
        upload_blob(&dest_client, bytes).await?;
        on_progress(i + 1, total);
    }

    // 3. Drain listMissingBlobs on the destination until it reports empty, bounded so a
    //    server that never converges errors instead of looping forever.
    for _ in 0..MAX_DRAIN_ITERATIONS {
        let mut cursor: Option<String> = None;
        let mut any_missing = false;
        loop {
            let (missing, next_cursor) = list_missing_blobs(&dest_client, cursor.as_deref()).await?;
            if !missing.is_empty() {
                any_missing = true;
            }
            match next_cursor {
                Some(c) => cursor = Some(c),
                None => break,
            }
        }
        if !any_missing {
            return Ok(());
        }
    }

    Err(MigrateError::MigrationNotReady {
        message: format!(
            "listMissingBlobs did not drain to empty after {MAX_DRAIN_ITERATIONS} attempts"
        ),
    })
}

/// Copy `app.bsky` preferences from source to destination for the migration parked in
/// `MigrationState` (requires both `source_oauth_client` and `dest_session`). The testable
/// core of `migration_transfer_preferences_cmd`.
pub async fn migration_transfer_preferences_impl(
    app_state: &crate::oauth::AppState,
    did: String,
) -> Result<(), MigrateError> {
    let (source_oauth_client, dest_client) = {
        let migration = app_state.migration_state.lock().await;
        let ms = migration
            .as_ref()
            .ok_or_else(|| MigrateError::MigrationNotReady {
                message: "no pending migration; call prepare_migration first".to_string(),
            })?;
        if ms.did != did {
            return Err(MigrateError::MigrationNotReady {
                message: format!(
                    "migration state DID mismatch: expected {}, got {did}",
                    ms.did
                ),
            });
        }
        let source_oauth_client =
            ms.source_oauth_client
                .clone()
                .ok_or_else(|| MigrateError::MigrationNotReady {
                    message: "source authentication missing; authenticate to the source PDS first"
                        .to_string(),
                })?;
        let dest_client = ms
            .dest_session
            .clone()
            .ok_or_else(|| MigrateError::MigrationNotReady {
                message: "destination session missing; create the destination account first"
                    .to_string(),
            })?;
        (source_oauth_client, dest_client)
    };

    let preferences = get_preferences(&source_oauth_client).await?;
    put_preferences(&dest_client, &preferences).await
}

