pub async fn list_blobs(
    pds_client: &PdsClient,
    source_base_url: &str,
    did: &str,
    cursor: Option<&str>,
) -> Result<(Vec<String>, Option<String>), MigrateError> {
    let mut url = format!(
        "{}/xrpc/com.atproto.sync.listBlobs?did={}",
        source_base_url.trim_end_matches('/'),
        urlencoding::encode(did)
    );
    if let Some(c) = cursor {
        url.push_str(&format!("&cursor={}", urlencoding::encode(c)));
    }

    let resp = pds_client
        .client()
        .get(&url)
        .send()
        .await
        .map_err(|e| MigrateError::NetworkError {
            message: format!("listBlobs request failed: {e}"),
        })?;

    let status = resp.status();
    if !status.is_success() {
        let body = resp
            .text()
            .await
            .unwrap_or_else(|_| "(response body unreadable)".to_string());
        return Err(MigrateError::NetworkError {
            message: format!("listBlobs returned {status}: {body}"),
        });
    }

    #[derive(Deserialize)]
    struct ListBlobsResponse {
        cids: Vec<String>,
        #[serde(default)]
        cursor: Option<String>,
    }
    let body: ListBlobsResponse = resp.json().await.map_err(|e| MigrateError::NetworkError {
        message: format!("failed to parse listBlobs response: {e}"),
    })?;

    Ok((body.cids, body.cursor))
}

