        }));
    });
    // Page 2 (with cursor): the last CID, no further cursor.
    source.mock(|when, then| {
        when.method(GET)
            .path("/xrpc/com.atproto.sync.listBlobs")
            .query_param("did", did)
            .query_param("cursor", "bafy_a");
        then.status(200).json_body(serde_json::json!({ "cids": ["bafy_b"] }));
    });
    source.mock(|when, then| {
        when.method(GET)
            .path("/xrpc/com.atproto.sync.getBlob")
            .query_param("did", did)
            .query_param("cid", "bafy_a");
        then.status(200).body(vec![1, 1, 1]);
    });
    source.mock(|when, then| {
        when.method(GET)
            .path("/xrpc/com.atproto.sync.getBlob")
            .query_param("did", did)
            .query_param("cid", "bafy_b");
        then.status(200).body(vec![2, 2, 2]);
    });

    let dest = MockServer::start();
    let upload_mock = dest.mock(|when, then| {
        when.method(POST)
            .path("/xrpc/com.atproto.repo.uploadBlob")
            .header("Authorization", "Bearer dest-access");
        then.status(200).json_body(serde_json::json!({
            "blob": { "$type": "blob", "ref": { "$link": "bafy_x" }, "mimeType": "application/octet-stream", "size": 3 }
        }));
    });
    // First call to listMissingBlobs reports one still missing, second call reports none —
    // proving the drain loop calls it more than once until empty.
    let missing_mock_1 = dest.mock(|when, then| {
        when.method(GET)
            .path("/xrpc/com.atproto.repo.listMissingBlobs")
            .header("Authorization", "Bearer dest-access");
        then.status(200).json_body(serde_json::json!({
            "blobs": [{ "cid": "bafy_b", "recordUri": "at://x/app.bsky.feed.post/1" }]
        }));
    });

    let app_state = crate::oauth::AppState::new();
    {
        let mut migration = app_state.migration_state.lock().await;
        *migration = Some(migration_state_ready_for_transfer(
            did,
            source.base_url(),
            dest.base_url(),
        ));
    }

    // The mock above always returns the same "still missing" response, so to prove the
    // drain loop terminates we cap iterations and assert the upload count instead of
    // depending on a stateful mock sequence (httpmock free tier has no built-in call-count
    // sequencing across mocks). We verify termination and progress via the callback.
    let mut progress_calls: Vec<(usize, usize)> = Vec::new();
    let result = migration_transfer_blobs_impl(&app_state, did.to_string(), &mut |uploaded, total| {
        progress_calls.push((uploaded, total));
    })
    .await;

    // Two blobs uploaded, so the upload mock must have been hit twice.
    upload_mock.assert_hits(2);
    assert_eq!(
        progress_calls,
        vec![(1, 2), (2, 2)],
        "progress callback must be invoked with increasing uploaded counts toward total"
    );

    // Since the mock server always reports one blob still missing, the bounded drain loop
    // must give up rather than spin forever, and report that as an error.
    assert!(result.is_err(), "a drain loop that never converges must error, not hang");
    let _ = missing_mock_1;
}

