/// Tauri command: transfer every referenced blob from source to destination, emitting
/// `migration_blob_progress` events as the upload proceeds.
#[tauri::command]
pub async fn migration_transfer_blobs_cmd(
    app: tauri::AppHandle,
    state: tauri::State<'_, crate::oauth::AppState>,
    did: String,
) -> Result<(), MigrateError> {
    migration_transfer_blobs_impl(&state, did, &mut |uploaded, total| {
        if let Err(e) = app.emit(
            "migration_blob_progress",
            MigrationBlobProgress { uploaded, total },
        ) {
            tracing::warn!(error = %e, "failed to emit migration_blob_progress event");
        }
    })
    .await
}

