pub struct CheckAccountStatus {
    /// `true` when the destination account is active (not deactivated).
    pub activated: bool,
    /// `true` when the account has a DID document in the PLC directory cache.
    pub valid_did: bool,
    /// The repo's root commit CID, or `None` when there is no repo yet.
    #[serde(default)]
    pub repo_commit: Option<String>,
    /// The repo's commit revision (TID), or `None` when there is no repo.
    #[serde(default)]
    pub repo_rev: Option<String>,
    /// Total blocks stored for this DID in the destination's block store.
    #[serde(default)]
    pub stored_blocks: i64,
    /// Number of records indexed in the repo.
    pub indexed_records: u64,
    /// Number of private state values (always 0 on ezpds).
    #[serde(default)]
    pub private_state_values: u64,
    /// Number of distinct blob CIDs referenced by repo records.
    pub expected_blobs: u64,
    /// Number of blobs actually imported into the destination's blob store.
    pub imported_blobs: u64,
}

