// ── migrate (full outbound orchestration) ─────────────────────────────────────

/**
 * Destination account import status, returned by `migrationVerify`.
 * Matches CheckAccountStatus in migrate.rs (`#[serde(rename_all = "camelCase")]`).
 */
export interface CheckAccountStatus {
  activated: boolean;
  validDid: boolean;
  repoCommit: string | null;
  repoRev: string | null;
  storedBlocks: number;
  indexedRecords: number;
  privateStateValues: number;
  expectedBlobs: number;
  importedBlobs: number;
}

/** Payload of the `migration_blob_progress` Tauri event (running uploaded/total counts). */
export interface MigrationBlobProgress {
  uploaded: number;
  total: number;
}

/** Tauri event emitted during the blob-transfer leg; listen with `@tauri-apps/api/event`. */
export const MIGRATION_BLOB_PROGRESS_EVENT = 'migration_blob_progress';

/**
 * Start an outbound migration: resolve the identity's source PDS, discover the destination's
 * service DID, detect the migration path, and park MigrationState. Returns the path decision so
 * the UI can branch (self_signed proceeds; interop / cannot_determine stop with a message).
 */
export const prepareMigration = (
  did: string,
  destPdsUrl: string,
): Promise<MigrationPathDecision> => invoke('prepare_migration_cmd', { did, destPdsUrl });

/**
 * Authenticate to the identity's SOURCE PDS via the in-app OAuth session (same three-step shape
 * as `startPdsAuth`), storing the source client in MigrationState. Resolves when complete.
 */
export const startMigrationSourceAuth = async (did: string): Promise<void> => {
  const prepared = await invoke<{ authUrl: string; callbackScheme: string }>(
    'migration_prepare_source_auth_cmd',
    { did },
  );
  let callbackUrl: string;
  try {
    callbackUrl = await invoke<string>('plugin:auth-session|start', {
      authUrl: prepared.authUrl,
      callbackUrlScheme: prepared.callbackScheme,
    });
  } catch {
    // A dismissed sheet reads as "not ready to continue"; the UI offers a retry.
    throw { code: 'MIGRATION_NOT_READY', message: 'source authentication was cancelled' } as MigrateError;
  }
  await invoke('migration_complete_source_auth_cmd', { callbackUrl });
};

/** Provision the deactivated destination account (reserveSigningKey → getServiceAuth → createAccount). */
export const migrationCreateDestAccount = (
  did: string,
  handle: string,
  email: string,
): Promise<void> => invoke('migration_create_dest_account_cmd', { did, handle, email });

/** Transfer the repo CAR from source to destination. */
export const migrationTransferRepo = (did: string): Promise<void> =>
  invoke('migration_transfer_repo_cmd', { did });

/** Transfer every referenced blob from source to destination (emits `migration_blob_progress`). */
export const migrationTransferBlobs = (did: string): Promise<void> =>
  invoke('migration_transfer_blobs_cmd', { did });

/** Copy `app.bsky` preferences from source to destination. */
export const migrationTransferPreferences = (did: string): Promise<void> =>
  invoke('migration_transfer_preferences_cmd', { did });

/** Report the destination account's import completeness before the identity leg. */
export const migrationVerify = (did: string): Promise<CheckAccountStatus> =>
  invoke('migration_verify_cmd', { did });

/** Finalize: activate the destination, deactivate the source, and clear migration state. */
export const migrationFinalize = (did: string): Promise<void> =>
  invoke('migration_finalize_cmd', { did });

