/**
 * Prompt for biometric authentication (Face ID / Touch ID) via `tauri-plugin-biometric`.
 * Resolves on success; rejects (with the plugin's string reason) if the user cancels or fails.
 * Gates the PLC-op submission in the migration review screen — the user is the signer, so this
 * is the authorization boundary, not decorative confirmation.
 */
export const authenticateBiometric = (reason: string): Promise<void> =>
  invoke('plugin:biometric|authenticate', {
    reason,
    // Require a genuine biometric match; do not silently fall back to the device passcode.
    allowDeviceCredential: false,
  });

