79	        case 'IDENTITY_NOT_FOUND':
80	          return { message: 'This identity could not be found.', terminal: true };
81	        case 'MIGRATION_NOT_READY':
82	          return { message: 'Migration is not ready yet. Please restart the migration flow.', terminal: true };
83	        default:
