25	    did: string;
26	    handle: string;
27	    email: string;
28	    onnext: (status: CheckAccountStatus) => void;
29	    onerror: (err: MigrateError) => void;
30	  } = $props();
31	
32	  type LegId = 'account' | 'repo' | 'blobs' | 'preferences' | 'verify';
33	  type LegState = 'pending' | 'active' | 'done' | 'failed';
34	
35	  const LEGS: { id: LegId; label: string }[] = [
36	    { id: 'account', label: 'Create destination account' },
37	    { id: 'repo', label: 'Transfer repository' },
38	    { id: 'blobs', label: 'Transfer blobs' },
39	    { id: 'preferences', label: 'Transfer preferences' },
40	    { id: 'verify', label: 'Verify destination' },
41	  ];
42	
43	  let legStates = $state<Record<LegId, LegState>>({
44	    account: 'pending',
45	    repo: 'pending',
46	    blobs: 'pending',
47	    preferences: 'pending',
48	    verify: 'pending',
49	  });
50	
51	  let blobProgress = $state<MigrationBlobProgress | null>(null);
52	  let unlisten: UnlistenFn | null = null;
53	
54	  function statusGlyph(state: LegState): string {
55	    switch (state) {
56	      case 'pending':
57	        return '○';
58	      case 'active':
59	        return '◐';
60	      case 'done':
61	        return '✓';
62	      case 'failed':
63	        return '✕';
64	    }
65	  }
66	
67	  function statusWord(state: LegState): string {
68	    switch (state) {
69	      case 'pending':
70	        return 'Waiting';
71	      case 'active':
72	        return 'In progress';
73	      case 'done':
74	        return 'Done';
75	      case 'failed':
76	        return 'Failed';
77	    }
78	  }
79	
80	  async function runLeg(id: LegId, fn: () => Promise<void>) {
81	    legStates[id] = 'active';
82	    await fn();
83	    legStates[id] = 'done';
84	  }
85	
86	  async function runMigration() {
87	    try {
88	      await runLeg('account', () => migrationCreateDestAccount(did, handle, email));
89	      await runLeg('repo', () => migrationTransferRepo(did));
90	      await runLeg('blobs', () => migrationTransferBlobs(did));
91	      await runLeg('preferences', () => migrationTransferPreferences(did));
92	
93	      legStates.verify = 'active';
94	      const status = await migrationVerify(did);
95	      legStates.verify = 'done';
96	
97	      onnext(status);
98	    } catch (raw: unknown) {
99	      console.error('Migration leg failed:', raw);
100	      // Mark whichever leg is still 'active' as failed.
101	      for (const leg of LEGS) {
102	        if (legStates[leg.id] === 'active') {
103	          legStates[leg.id] = 'failed';
104	        }
105	      }
106	
107	      if (isCodedError(raw)) {
108	        onerror(raw as MigrateError);
109	      } else {
110	        onerror({ code: 'NETWORK_ERROR', message: 'An unexpected error occurred.' });
111	      }
112	    }
113	  }
114	
115	  onMount(async () => {
116	    unlisten = await listen<MigrationBlobProgress>(MIGRATION_BLOB_PROGRESS_EVENT, (event) => {
117	      blobProgress = event.payload;
118	    });
119	    runMigration();
120	  });
121	
122	  onDestroy(() => {
123	    unlisten?.();
124	  });
125	</script>
