22	/// Extract the `exp` claim from a JWT's payload.
23	///
24	/// Splits the token on `.`, base64url-decodes the payload segment, and parses it as JSON.
25	/// Returns `None` on any failure (malformed token, missing exp, unparseable JSON, etc.).
26	fn jwt_exp_claim(token: &str) -> Option<u64> {
27	    use base64::engine::general_purpose::URL_SAFE_NO_PAD;
28	    use base64::Engine;
29	
30	    let parts: Vec<&str> = token.split('.').collect();
31	    if parts.len() < 2 {
32	        return None;
33	    }
34	
35	    let payload_bytes = URL_SAFE_NO_PAD.decode(parts[1]).ok()?;
36	    let payload: serde_json::Value = serde_json::from_slice(&payload_bytes).ok()?;
37	    payload.get("exp")?.as_u64()
38	}
