40	/// How this client authenticates its XRPC requests.
41	///
42	/// `Dpop` is the wallet's normal OAuth mode (DPoP-bound access token + proof header,
43	/// refresh via `/oauth/token`). `Bearer` is the legacy session mode used ONLY for the
44	/// migrated (deactivated) destination account, whose credentials are the plain
45	/// `accessJwt`/`refreshJwt` that migration-mode `createAccount` returns.
46	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
47	enum AuthMode {
48	    Dpop,
49	    Bearer,
50	}
51	
52	/// Authenticated HTTP client.
53	///
54	/// Wraps every request with:
55	/// - `Authorization: DPoP {access_token}` header
56	/// - `DPoP: {proof}` header containing a fresh ES256 JWT with `ath` claim
57	///
58	/// Transparently refreshes the access token when it has less than 60 seconds remaining.
59	/// Retries once on `use_dpop_nonce` 400 responses.
60	pub struct OAuthClient {
61	    inner: Client,
62	    dpop: DPoPKeypair,
63	    session: Arc<Mutex<OAuthSession>>,
64	    base_url: String,
65	    auth_mode: AuthMode,
66	}
67	
68	impl OAuthClient {
69	    /// Construct from an existing session.
70	    ///
71	    /// Loads the DPoP keypair from Keychain (same key used in the original flow).
72	    ///
73	    /// `Client::new()` inherits the TLS backend configured at the crate level via Cargo features
74	    /// (`default-features = false, features = ["rustls-tls"]` in Cargo.toml). No builder
75	    /// configuration is needed — the feature flags apply crate-wide, not per-client-instance.
76	    pub fn new(session: Arc<Mutex<OAuthSession>>, base_url: String) -> Result<Self, OAuthError> {
77	        let dpop = DPoPKeypair::get_or_create()?;
78	        Ok(Self {
79	            inner: Client::new(),
80	            dpop,
81	            session,
82	            base_url,
83	            auth_mode: AuthMode::Dpop,
84	        })
85	    }
86	
87	    /// Build a Bearer-session client for a migrated destination account. `access_jwt` /
88	    /// `refresh_jwt` are the legacy tokens returned by migration-mode `createAccount`.
89	    /// `expires_at` is derived from the access token's `exp` claim so proactive refresh works.
90	    pub fn new_bearer(
91	        access_jwt: String,
92	        refresh_jwt: String,
93	        base_url: String,
94	    ) -> Result<Self, OAuthError> {
95	        let expires_at = jwt_exp_claim(&access_jwt).unwrap_or(0);
96	        let session = OAuthSession {
97	            access_token: access_jwt,
98	            refresh_token: refresh_jwt,
