export const authenticateBiometric = async (reason: string): Promise<void> => {
  // This is the authorization boundary for an irreversible identity change, not a
  // decorative confirmation, so it must fail CLOSED. The ONLY failure we treat as "no gate
  // to enforce" is the plugin import itself failing: the plugin exists only on iOS/Android,
  // so off-device (desktop dev, host build) the dynamic import throws and there is nothing
  // to gate against. Any checkStatus/authenticate rejection on a real device — a transient
  // keystore/permission error, an operator cancel, a failed match — must propagate so a
  // momentary hiccup can never silently skip the gate. (Mirrors admin-companion's
  // requireUserPresence, which likewise catches only the import.)
  let plugin: typeof import('@tauri-apps/plugin-biometric');
  try {
    plugin = await import('@tauri-apps/plugin-biometric');
  } catch {
    return; // plugin not present (desktop dev / host build) — nothing to gate against.
  }
  const { isAvailable } = await plugin.checkStatus();
  if (!isAvailable) return; // no enrolled hardware (e.g. a bare simulator) — nothing to gate.
  await plugin.authenticate(reason, { allowDeviceCredential: true });
};

